	'qr_codes.guide_card_2_title' => 'Prilagođeno za print i offline rad',
	'qr_codes.guide_card_2_text' => 'Ovi QR kodovi idealni su za letke, vizitke, plakate, brošure, stolove na događajima, pakiranja proizvoda i sve situacije gdje ljudi skeniraju umjesto da tipkaju.',
	'qr_codes.guide_card_3_title' => 'Pravilno prilagodi i izvezi',
	'qr_codes.guide_card_3_text' => 'Podesite tip QR-a, stil, boje, okvir, logo, branding i izlazni format kako bi konačni QR odgovarao kontekstu u kojem će se koristiti.',
