	'qr_codes.empty_title' => 'Kreirajte svoj prvi QR kod',
	'qr_codes.empty_text' => 'Krenite sa zasebnim QR kodom za link, aplikaciju, kontakt, događaj ili print materijal. Nakon kreiranja uvijek se možete vratiti i doraditi stil, okvir, branding i format izvoza.',
	'qr_codes.tour.create_title' => 'Kreirajte zaseban QR kod',
